{{ printf "" .Permalink .MediaType | safeHTML }}
{{- end }}
{{- range $items }}


  {{ .Title }}
  {{ with .Params.externalURL }}{{ . }}{{ else }}{{ .Permalink }}{{ end }}
  {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
  {{ .Permalink }}
  {{ with .Params.description }}{{ . }}{{ else }}{{ .Summary | html }}{{ end }}

{{- end }}
